import {
  ChangeDetectionStrategy,
  Component,
  Input
} from '@angular/core';

import {
  MerkazHaarachaHashvaa,
  MiddaTziyunHashvaa,
  StatusHashvaa,
  SugRamatTziyun
} from '../../models/hashvaat-grid.model';

@Component({
  selector: 'app-tziyunim-moamad',
  templateUrl: './tziyunim-moamad.component.html',
  styleUrls: ['./tziyunim-moamad.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class TziyunimMoamadComponent {

  @Input() midot: MiddaTziyunHashvaa[] = [];
  @Input() merkazim: MerkazHaarachaHashvaa[] = [];
  @Input() statusim: StatusHashvaa[] = [];

  getClassRama(sugRama?: SugRamatTziyun): string {
    if (!sugRama || sugRama === 'ragil') {
      return '';
    }
    return 'tziyunim-moamad__badge--' + sugRama;
  }

  getClassStatus(status: StatusHashvaa): string {
    const classes = ['tziyunim-moamad__status', 'tziyunim-moamad__status--' + status.sug];
    if (status.isPill) {
      classes.push('tziyunim-moamad__status--pill');
    }
    return classes.join(' ');
  }

  trackByMidda(index: number, midda: MiddaTziyunHashvaa): string {
    return midda && midda.shem ? midda.shem : String(index);
  }

  trackByMerkaz(index: number, merkaz: MerkazHaarachaHashvaa): string {
    return merkaz && merkaz.shem ? merkaz.shem : String(index);
  }

  trackByStatus(index: number, status: StatusHashvaa): string {
    return status && status.tekst ? status.tekst : String(index);
  }
}
