import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  ElementRef,
  HostListener,
  Input
} from '@angular/core';

/** גודל פופאפ כמו בפיגמה: 260×260 */
const GODEL_POPUP_PX = 260;
const OFFSET_POPUP_PX = 8;

@Component({
  selector: 'app-tmunat-moamad',
  templateUrl: './tmunat-moamad.component.html',
  styleUrls: ['./tmunat-moamad.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class TmunatMoamadComponent {

  /** כתובת התמונה */
  @Input() urlTmuna = '';

  /** שם לתצוגה בפופאפ */
  @Input() shemMale = '';

  /** צבע מסגרת + תג שם */
  @Input() colorLeMoamad = '#4f46e5';

  /** גודל התמונה הקטנה */
  @Input() godel = '2.5rem';

  /** עובי מסגרת התמונה הקטנה */
  @Input() oviMisgeret = '0.1875rem';

  isPopupPatuach = false;
  stylePopup: { [key: string]: string } = {};

  constructor(
    private elementRef: ElementRef,
    private changeDetectorRef: ChangeDetectorRef
  ) {
  }

  get styleThumb(): { [key: string]: string } {
    return {
      width: this.godel || '2.5rem',
      height: this.godel || '2.5rem',
      borderWidth: this.oviMisgeret || '0.1875rem',
      borderColor: this.colorLeMoamad || '#4f46e5'
    };
  }

  onMouseEnter(): void {
    if (!this.urlTmuna) {
      return;
    }
    const rect = this.elementRef.nativeElement.getBoundingClientRect();
    const left = rect.left + rect.width / 2 - GODEL_POPUP_PX / 2;
    const top = rect.bottom + OFFSET_POPUP_PX;

    this.stylePopup = {
      position: 'fixed',
      left: Math.max(8, left) + 'px',
      top: top + 'px',
      zIndex: '9999'
    };
    this.isPopupPatuach = true;
    this.changeDetectorRef.markForCheck();
  }

  onMouseLeave(): void {
    this.isPopupPatuach = false;
    this.changeDetectorRef.markForCheck();
  }

  @HostListener('window:scroll')
  onScroll(): void {
    if (this.isPopupPatuach) {
      this.isPopupPatuach = false;
      this.changeDetectorRef.markForCheck();
    }
  }
}
