import {
  Component,
  ChangeDetectionStrategy,
  Input,
  Output,
  EventEmitter
} from '@angular/core';

import {
  AmudaTable,
  ErechTaTable,
  IruaLichitzaTable,
  NetuneiTableHashvaa,
  ShuraTable,
  SugMegamaTable,
  TaBoletLechiyuv,
  TaMegama,
  TaMikom,
  TaPeulatHaarcha,
  TaShemMoamad
} from '../../models/table-hashvaa.model';

@Component({
  selector: 'app-table',
  templateUrl: './table.component.html',
  styleUrls: ['./table.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class TableComponent {

  @Input() netuneiTable: NetuneiTableHashvaa = { amudot: [], shurot: [] };

  @Output() tzfiaMoamad = new EventEmitter<IruaLichitzaTable>();
  @Output() peulatHaarcha = new EventEmitter<IruaLichitzaTable>();
  @Output() lichitzatTa = new EventEmitter<IruaLichitzaTable>();

  get amudot(): AmudaTable[] {
    return this.netuneiTable && this.netuneiTable.amudot
      ? this.netuneiTable.amudot
      : [];
  }

  get shurot(): ShuraTable[] {
    return this.netuneiTable && this.netuneiTable.shurot
      ? this.netuneiTable.shurot
      : [];
  }

  /** רוחב מינימלי דינמי לטבלה לפי מספר עמודות מועמדים */
  get minWidthTable(): string {
    const kamutAmudot = this.amudot.length;
    if (kamutAmudot <= 0) {
      return '100%';
    }

    let sumRem = 0;
    for (let i = 0; i < this.amudot.length; i++) {
      sumRem += this.getMinWidthRemLeAmuda(this.amudot[i]);
    }

    return Math.max(sumRem, 20) + 'rem';
  }

  getMinWidthStyle(amuda: AmudaTable): string {
    if (amuda && amuda.minWidth) {
      return amuda.minWidth;
    }
    return this.getMinWidthRemLeAmuda(amuda) + 'rem';
  }

  getErech(shura: ShuraTable, amuda: AmudaTable): ErechTaTable {
    if (!shura || !amuda) {
      return null;
    }
    return shura[amuda.mafteach];
  }

  getTekstPashut(erech: ErechTaTable): string {
    if (erech === null || erech === undefined) {
      return '';
    }
    if (typeof erech === 'object') {
      return '';
    }
    return String(erech);
  }

  getShemMoamad(erech: ErechTaTable): TaShemMoamad {
    if (erech && typeof erech === 'object' && 'tekst' in erech) {
      return erech as TaShemMoamad;
    }
    if (typeof erech === 'string') {
      return { tekst: erech };
    }
    return { tekst: '' };
  }

  getMikom(erech: ErechTaTable): TaMikom {
    if (erech && typeof erech === 'object' && 'mikom' in erech) {
      return erech as TaMikom;
    }
    return { mikom: 0, miKamut: 0 };
  }

  getTekstMikom(erech: ErechTaTable): string {
    const mikom = this.getMikom(erech);
    if (!mikom.mikom || !mikom.miKamut) {
      return this.getTekstPashut(erech);
    }
    return mikom.mikom + ' מתוך ' + mikom.miKamut;
  }

  getSugMikom(erech: ErechTaTable): 'zahav' | 'kesef' | 'arad' | 'ragil' {
    const mikom = this.getMikom(erech).mikom;
    if (mikom === 1) {
      return 'zahav';
    }
    if (mikom === 2) {
      return 'kesef';
    }
    if (mikom === 3) {
      return 'arad';
    }
    return 'ragil';
  }

  getTziyunMispar(erech: ErechTaTable): number | null {
    if (typeof erech === 'number' && !isNaN(erech)) {
      return erech;
    }
    if (typeof erech === 'string' && erech !== '' && !isNaN(Number(erech))) {
      return Number(erech);
    }
    return null;
  }

  getBolet(erech: ErechTaTable): TaBoletLechiyuv {
    if (typeof erech === 'boolean') {
      return { isBolet: erech, tekst: erech ? 'כן' : 'לא' };
    }
    if (erech && typeof erech === 'object' && 'isBolet' in erech) {
      const bolet = erech as TaBoletLechiyuv;
      return {
        isBolet: !!bolet.isBolet,
        tekst: bolet.tekst || (bolet.isBolet ? 'כן' : 'לא')
      };
    }
    return { isBolet: false, tekst: '' };
  }

  getMegama(erech: ErechTaTable): TaMegama {
    if (erech && typeof erech === 'object' && 'sug' in erech) {
      const megama = erech as TaMegama;
      return {
        sug: megama.sug,
        tekst: megama.tekst || this.getTekstDefaultLeMegama(megama.sug)
      };
    }
    if (typeof erech === 'string') {
      return { sug: 'yatziv', tekst: erech };
    }
    return { sug: 'yatziv', tekst: '' };
  }

  getPeulatHaarcha(erech: ErechTaTable): TaPeulatHaarcha {
    if (erech && typeof erech === 'object' && 'moamadId' in erech) {
      return erech as TaPeulatHaarcha;
    }
    return {};
  }

  isTziyunMaxBaShura(shura: ShuraTable, amuda: AmudaTable): boolean {
    if (!amuda || !amuda.hadgeshMaxBaShura || amuda.sug !== 'tziyun') {
      return false;
    }

    const erechNochachi = this.getTziyunMispar(this.getErech(shura, amuda));
    if (erechNochachi === null) {
      return false;
    }

    let maxErech: number | null = null;
    for (let i = 0; i < this.amudot.length; i++) {
      const amudaAcheret = this.amudot[i];
      if (
        !amudaAcheret
        || amudaAcheret.sug !== 'tziyun'
        || !amudaAcheret.hadgeshMaxBaShura
      ) {
        continue;
      }
      const erech = this.getTziyunMispar(this.getErech(shura, amudaAcheret));
      if (erech === null) {
        continue;
      }
      if (maxErech === null || erech > maxErech) {
        maxErech = erech;
      }
    }

    return maxErech !== null && erechNochachi === maxErech;
  }

  getYishurClass(amuda: AmudaTable): string {
    const yishur = amuda && amuda.yishur ? amuda.yishur : this.getYishurDefault(amuda);
    return 'table-hashvaa__ta--' + yishur;
  }

  onLichitzatShemMoamad(amuda: AmudaTable, shura: ShuraTable): void {
    const irua = this.bniyatIrua(amuda, shura);
    this.tzfiaMoamad.emit(irua);
    this.lichitzatTa.emit(irua);
  }

  onLichitzatHaarcha(amuda: AmudaTable, shura: ShuraTable): void {
    const irua = this.bniyatIrua(amuda, shura);
    this.peulatHaarcha.emit(irua);
    this.lichitzatTa.emit(irua);
  }

  trackByAmuda(index: number, amuda: AmudaTable): string {
    return amuda && amuda.mafteach ? amuda.mafteach : String(index);
  }

  trackByShura(index: number, shura: ShuraTable): string | number {
    return shura && shura.id !== undefined && shura.id !== null
      ? shura.id
      : index;
  }

  private bniyatIrua(amuda: AmudaTable, shura: ShuraTable): IruaLichitzaTable {
    return {
      amuda: amuda,
      shura: shura,
      erech: this.getErech(shura, amuda)
    };
  }

  private getYishurDefault(amuda: AmudaTable): string {
    if (!amuda) {
      return 'center';
    }
    if (amuda.sug === 'text' || amuda.sug === 'shem-moamad' || amuda.sug === 'megama') {
      return amuda.sug === 'megama' ? 'center' : 'right';
    }
    return 'center';
  }

  private getTekstDefaultLeMegama(sug: SugMegamaTable): string {
    if (sug === 'aliya') {
      return 'מגמת עלייה';
    }
    if (sug === 'yerida') {
      return 'מגמת ירידה';
    }
    return 'יציב';
  }

  private getMinWidthRemLeAmuda(amuda: AmudaTable): number {
    if (!amuda) {
      return 6;
    }
    if (amuda.minWidth) {
      const parsed = parseFloat(amuda.minWidth);
      return isNaN(parsed) ? 6 : parsed;
    }
    switch (amuda.sug) {
      case 'text':
        return 9;
      case 'shem-moamad':
        return 8;
      case 'tziyun':
        return 5.5;
      case 'mikom':
        return 6;
      case 'tziyun-shana':
        return 4.5;
      case 'bolet-lechiyuv':
        return 7;
      case 'megama':
        return 8;
      case 'peulat-haarcha':
        return 4.5;
      default:
        return 6;
    }
  }
}
